query:
query dashboard {
  viewer {
    id
    firstName
    lastName
    ... on Member {
      tosAccepted
      membershipExpires
      fee {
        total
        __typename
      }
      matches {
        type
        ...matchListItem
        __typename
      }
      leagues(current: true) {
        id
        slug
        __typename
      }
      __typename
    }
    ... on ExternalStaff {
      leagues {
        id
        slug
        __typename
      }
      __typename
    }
    __typename
  }
}

fragment matchListItem on Match {
  id
  isBye
  status
  scoresheet
  startTime
  isMine
  isPaid
  isTournament
  isScored
  isFinalized
  isPlayoff
  description
  tableNumber
  results {
    homeAway
    points {
      total
      __typename
    }
    __typename
  }
  timeZone {
    id
    name
    __typename
  }
  location {
    id
    name
    address {
      id
      name
      __typename
    }
    __typename
  }
  home {
    id
    name
    number
    isMine
    __typename
  }
  away {
    id
    name
    number
    isMine
    __typename
  }
  league {
    id
    isMine
    slug
    isElectronicPaymentsEnabled
    __typename
  }
  orderItems {
    id
    order {
      id
      member {
        id
        firstName
        lastName
        __typename
      }
      __typename
    }
    __typename
  }
  division {
    id
    scheduleInEdit
    isTournament
    __typename
  }
  __typename
}
